BASE='https://ogogoeva.ru/'
DATA=[
 dict(slug='individual-therapy',kind='service',image='collage-journal.webp',ru=dict(title='Индивидуальная терапия онлайн — КПТ и ДБТ | Анастасия Гоева',h1='Индивидуальная терапия онлайн',intro='Когда тревога, самокритика или сложные отношения занимают слишком много места в жизни, на встречах можно постепенно разобраться в происходящем и понять, что вы хотите изменить.',desc='Индивидуальные онлайн-консультации с Анастасией Гоевой. КПТ, ДБТ и ЛОРПТ: работа с тревогой, паническими атаками, самокритикой и трудностями пищевого поведения.',sections=[('С чем можно прийти','<p>Я работаю со взрослыми, которых изматывают тревога, панические атаки или навязчивые мысли, которым трудно справляться с самокритикой, чувством вины и стыда. На консультации также можно обсудить трудности пищевого поведения, выгорание, потерю интереса к привычным занятиям и сложности в близких отношениях.</p><p>Иногда запрос звучит вполне определённо: «Мне трудно отстаивать свои границы». Иногда пока есть только ощущение, что так, как сейчас, больше не хочется. Можно начать и с конкретной темы, и с общего ощущения, что хочется перемен. На первой встрече я помогу уточнить, что для вас особенно важно.</p>'),('Как я выбираю подход','<p>В индивидуальной работе я опираюсь на когнитивно-поведенческую терапию (КПТ), диалектическую поведенческую терапию (ДБТ) и личностно-ориентированную реконструктивную психотерапию (ЛОРПТ). Мы обсуждаем конкретные ситуации из вашей жизни и выбираем, на чём сейчас полезнее сосредоточиться.</p><p>В КПТ мы исследуем связь мыслей, эмоций и действий, проверяем привычные выводы и пробуем другие способы реагировать. Навыки ДБТ могут стать частью работы с сильными эмоциями, импульсивными реакциями и границами. ЛОРПТ помогает нам исследовать связь прошлого опыта с ожиданиями от себя и других и повторяющимися ситуациями в отношениях.</p>'),('Что происходит на первой встрече','<p>Первая сессия — полноценная платная консультация. Я выслушаю вас, задам уточняющие вопросы и помогу определить, с чем мы будем работать. Обсудим ваши ожидания, возможные цели и формат следующих встреч.</p><p>Можно заранее рассказать о диагнозе, назначенных препаратах или предыдущем опыте терапии, если это относится к вашему обращению. Я не назначаю лекарства; необходимость консультации врача мы можем обсудить отдельно.</p>'),('Что происходит между встречами','<p>По ходу работы мы возвращаемся к тому, что меняется в обычной жизни: стало ли легче замечать тревогу, говорить о своих потребностях или выдерживать сложный разговор. Иногда я предлагаю наблюдение или небольшое упражнение, чтобы вместе разобраться, что вам подходит.</p><p>Продолжительность терапии зависит от запроса и того, как идёт наша работа. На первой встрече можно обсудить регулярность, а затем возвращаться к этому вопросу по мере необходимости. Решение о продолжении мы принимаем вместе, учитывая ваши потребности и мои профессиональные возможности.</p>')],format='50 минут · онлайн · для взрослых',cta='Записаться индивидуально',other='Как проходит парная терапия',related='couples-therapy.html'),en=dict(title='Online Individual Therapy | Anastasia Goeva',h1='Individual therapy online',intro='If anxiety, self-criticism, or difficult relationships are taking up too much space in your life, therapy offers room to explore what is happening and what you would like to change.',desc='Online individual therapy with Anastasia Goeva. CBT, DBT skills and reconstructive psychotherapy for anxiety, self-criticism, relationship and eating difficulties.',sections=[('What you can bring to therapy','<p>I work with adults who feel worn down by anxiety, panic attacks, intrusive thoughts, self-criticism, guilt, or shame. We can also talk about eating difficulties, burnout, loss of interest in everyday life, and patterns in close relationships.</p><p>You might have a clear concern, such as finding it hard to set boundaries. Or you may simply feel that you want things to be different. Either is a starting point; we can work together to put what matters to you into words.</p>'),('How I approach our work','<p>My individual work draws on cognitive behavioral therapy (CBT), dialectical behavior therapy (DBT), and personality-oriented reconstructive psychotherapy. We look at real situations from your life and decide together what would be useful to focus on.</p><p>In CBT, we explore how thoughts, emotions, and actions influence one another, test familiar assumptions, and try different responses. DBT skills can be part of working with intense emotions, impulses, and boundaries. Reconstructive psychotherapy gives us a way to explore how past experiences connect with present expectations and recurring relationship patterns.</p>'),('Our first session','<p>The first meeting is a full-length, paid session. I will listen, ask questions, and help clarify what you want support with. We will talk about your expectations, possible goals, and how future sessions could work.</p><p>Please let me know about any diagnosis, prescribed medication, or previous therapy that is relevant to what brings you here. I do not prescribe medication. We can discuss whether speaking to a medical professional would be helpful.</p>'),('Between sessions','<p>We return to what changes in daily life: whether you notice anxiety sooner, find it easier to express a need, or respond differently in a difficult conversation. At times I may suggest a small exercise or something to notice so we can explore what works for you.</p><p>How long we work together depends on your concerns and how the work develops. We can discuss a meeting schedule at the start and review it along the way. Decisions about continuing take your needs and my professional scope into account.</p>')],format='50 minutes · online · adults',cta='Book an individual session',other='Explore couples therapy',related='couples-therapy-en.html')),
 dict(slug='couples-therapy',kind='service',image='collage-couple.webp',ru=dict(title='Семейный психолог онлайн — ЭФТ для пар | Анастасия Гоева',h1='Парная терапия онлайн',intro='Если разговоры снова заканчиваются одной и той же ссорой, вы чувствуете отдаление или вам трудно договориться о важном, это можно исследовать вместе на встрече.',desc='Парная терапия онлайн с семейным психологом Анастасией Гоевой. Эмоционально-фокусированный подход (ЭФТ): повторяющиеся ссоры, отдаление и трудности доверия.',sections=[('Когда можно обратиться вдвоём','<p>Ко мне приходят пары, которые устали от повторяющихся ссор, чувствуют, что их не слышат, или замечают, что совместная жизнь стала похожа на соседство. Поводом для встречи могут быть трудности доверия, перемены после переезда или рождения ребёнка, а также переживание утраты.</p><p>Можно обратиться и тогда, когда вы не знаете, как быть дальше: хотите попробовать восстановить близость, понять потребности друг друга или договориться о взаимодействии после расставания. На первой встрече мы обсудим, с какой задачей пришли вы оба.</p>'),('Как я работаю в ЭФТ','<p>В работе с парами я использую эмоционально-фокусированную терапию (ЭФТ, или EFT). Мы замечаем, как устроен повторяющийся цикл между вами: что запускает напряжение, как каждый пытается справиться и в какой момент становится труднее услышать друг друга.</p><p>За привычными реакциями мы исследуем чувства и потребности, которые трудно выразить в ссоре. Я помогаю обоим участникам разобраться в происходящем и искать другой способ взаимодействия. На сессии важен опыт каждого из вас.</p>'),('Зачем нужны отдельные встречи','<p>Обычно после одной-двух совместных сессий я предлагаю каждому одну-две отдельные встречи, после чего мы возвращаемся к общей работе. Они помогают лучше понять опыт каждого партнёра и то, что пока трудно сказать вдвоём.</p><p>Эти встречи остаются частью парной терапии. Мы заранее обсуждаем, как постепенно привносить значимую для пары информацию в совместную работу. Если вы хотите параллельно проходить индивидуальную терапию, для неё нужно выбрать другого специалиста.</p>'),('Первая встреча и дальнейшая работа','<p>Мы знакомимся, обсуждаем то, что беспокоит каждого, и определяем цели совместной работы. Можно говорить о сомнениях и о том, чего вы пока не готовы касаться. Важно, чтобы у обоих было время высказаться.</p><p>Регулярность и продолжительность мы обсуждаем с учётом ситуации пары. Точный срок и результат заранее не определяются: по ходу встреч мы возвращаемся к тому, какие изменения вы замечаете и что остаётся трудным.</p>'),('Как подготовиться к онлайн-сессии','<p>Выберите место, где вас не будут отвлекать, проверьте связь и устойчиво поставьте устройство. На время встречи отложите другие дела, чтобы вы оба могли говорить и слушать. Платформу и технические детали согласуем перед сессией.</p>')],format='80 минут · онлайн · для пары',cta='Записаться на парную встречу',other='Как проходит индивидуальная терапия',related='individual-therapy.html'),en=dict(title='Online Couples Therapy and EFT | Anastasia Goeva',h1='Couples therapy online',intro='If conversations keep ending in the same argument, you feel disconnected, or important decisions are hard to discuss, we can explore what is happening between you together.',desc='Online couples therapy with Anastasia Goeva. An emotionally focused approach (EFT) to recurring arguments, disconnection, and difficulties rebuilding trust.',sections=[('When to consider coming together','<p>Couples come to me when they are tired of familiar arguments, feel unheard, or notice that life together has started to feel like sharing a home without much closeness. Changes such as moving, having a baby, or coping with a loss may also bring you to therapy.</p><p>You can come if you are unsure what comes next: whether you want to rebuild closeness, understand each other better, or make arrangements after a separation. At our first meeting we will talk about what each of you hopes to work on.</p>'),('How I use EFT','<p>I use emotionally focused therapy (EFT) with couples. We look at the cycle that keeps happening between you: what starts the tension, how each person tries to cope, and when it becomes harder to hear one another.</p><p>We explore the feelings and needs behind familiar reactions, especially those that are difficult to express during an argument. My role is to help you both understand the pattern and explore different ways of responding. Both of you need space to be heard.</p>'),('Why we may meet individually','<p>After one or two joint sessions, I usually suggest one or two separate meetings with each partner before we return to working together. This helps me understand each person’s experience and what feels difficult to say in a joint session.</p><p>These meetings are part of the couples work. We discuss in advance how important information can be brought into joint sessions. If you would also like ongoing individual therapy, you will need a different therapist for that work.</p>'),('The first session and what follows','<p>We get to know one another, discuss what concerns each of you, and begin to agree on goals. You can talk about doubts and about subjects you are not ready to explore yet. Both partners need space to speak.</p><p>We will discuss frequency and duration in light of your situation. I cannot set an exact timeline or promise a particular outcome. We will keep reviewing what you notice changing and what remains difficult.</p>'),('Getting ready to meet online','<p>Choose a private place, check your connection, and put your device on a stable surface. Set aside other tasks so that you can both speak and listen. We will agree on the platform and any practical details before the session.</p>')],format='80 minutes · online · couples',cta='Book a couples session',other='Explore individual therapy',related='individual-therapy-en.html')),
 dict(slug='first-session',kind='article',image='collage-journal.webp',ru=dict(title='Как подготовиться к первой встрече с психологом онлайн | Анастасия Гоева',h1='Как подготовиться к первой встрече с психологом',intro='Перед первой встречей может быть трудно понять, что говорить, как сформулировать запрос и нужно ли заранее собираться с мыслями. Начать можно с того, что вы уже знаете о своём состоянии.',desc='Что рассказать психологу на первой встрече, как сформулировать запрос и подготовить место для онлайн-консультации. Материал Анастасии Гоевой.',sections=[('Что стоит подготовить заранее','<p>Для онлайн-встречи важно найти тихое место, где можно говорить свободно и где вас никто не побеспокоит. Проверьте интернет и звук, устойчиво поставьте телефон или ноутбук и отключите уведомления. Если дома есть ребёнок, заранее договоритесь, кто сможет побыть с ним во время сессии.</p><p>Если хотите, запишите несколько тем, которые занимают вас в последнее время. Это могут быть события, повторяющиеся разговоры, мысли или изменения в самочувствии. Подробная хронология всей жизни для начала не требуется: достаточно того, что сейчас кажется важным.</p>'),('Как говорить, если запрос пока неясен','<p>Можно начать с простой фразы: «Мне в последнее время тяжело, но я не понимаю почему». Или рассказать о конкретной ситуации, после которой вы решили записаться. Это примеры возможного начала разговора, а не готовая формула, которой нужно следовать.</p><p>На встрече я буду задавать вопросы и помогать уточнять, что вас беспокоит и каких изменений вам хочется. Если какую-то тему пока трудно обсуждать, об этом тоже можно сказать.</p>'),('Что мы будем обсуждать','<p>На первой встрече мы знакомимся, обсуждаем ваше обращение и ожидания от терапии. Если вы уже обращались к психологу, можно рассказать, что было полезным, а что не подошло. Если есть диагноз, назначенные лекарства или заключение психиатра, сообщите об этом в начале работы.</p><p>Моя первая сессия — полноценная платная консультация. В конце мы сможем обсудить, как могла бы выглядеть дальнейшая работа. Решение о продолжении остаётся за каждым из нас.</p>'),('О чём можно спросить психолога','<p>Вы можете уточнить, как устроен выбранный подход, как часто встречаться, как сохраняется конфиденциальность и что делать, если хочется перенести встречу. Полезно также обсудить, как мы будем замечать изменения по ходу терапии.</p><p>На моём сайте основные договорённости собраны в разделе «Перед записью», а стоимость и длительность — в разделе «Форматы и стоимость». Время и способ оплаты мы согласуем до встречи.</p>'),('Что можно заметить после встречи','<p>После разговора можно дать себе немного времени и спросить: удалось ли рассказать о важном, было ли понятно, что происходит, остались ли вопросы. Если появились сомнения, их можно обсудить со мной. Первая встреча помогает познакомиться и определить, подходит ли нам продолжать работу вместе.</p>')],cta='Обсудить первую встречу'),en=dict(title='How to Prepare for Your First Therapy Session | Anastasia Goeva',h1='Getting ready for your first therapy session',intro='Before a first appointment, you may wonder what to say, how to explain what is wrong, or whether you need to collect your thoughts first. You can begin with what you already know about how things have been for you.',desc='What to talk about in a first therapy session, how to explain your concerns, and how to prepare for an online appointment. A guide by Anastasia Goeva.',sections=[('Before we meet online','<p>Find a quiet, private place where you can speak freely without being interrupted. Check your internet connection and sound, place your phone or laptop on a stable surface, and turn off notifications. If you have a child at home, arrange for someone to look after them during the session.</p><p>If it helps, make a short note of a few things that have been on your mind. They might be events, recurring conversations, thoughts, or changes in how you feel. You can start with what matters now and share more of your history as it becomes relevant.</p>'),('If you do not know how to explain it yet','<p>You could begin with something as simple as, “Things have felt difficult lately, but I’m not sure why.” Or tell me about a particular moment that led you to book. These are examples of possible starting points; you can use your own words.</p><p>I will ask questions and help clarify what is troubling you and what you would like to change. You can also tell me when a subject feels too difficult to discuss for now.</p>'),('What we will talk about','<p>We will get to know one another and explore what brings you in and what you hope for from therapy. If you have seen a therapist before, you can share what helped and what did not work for you. Please mention any diagnosis, prescribed medication, or psychiatrist’s assessment at the start.</p><p>My first appointment is a full-length, paid session. Towards the end, we can discuss how working together might look. Each of us can decide whether to continue.</p>'),('Questions you can ask','<p>You are welcome to ask how I work, how often we might meet, how confidentiality works, and what happens if you need to reschedule. We can also discuss how we will notice change as the work develops.</p><p>You can find the main practical arrangements under “Before you book” and session lengths and fees under “Session formats and fees” on my website. We agree on a time and payment method before the appointment.</p>'),('After the session','<p>You might give yourself a little time to reflect on whether you could talk about what mattered, whether the process made sense, and what questions remain. If you have doubts, we can discuss them. The first meeting gives us a chance to get to know one another and decide whether working together feels right.</p>')],cta='Ask about a first session')),
 dict(slug='thoughts-emotions-behavior',kind='article',image='collage-anxiety.webp',ru=dict(title='Мысли, эмоции и поведение: как они связаны в КПТ | Анастасия Гоева',h1='Мысли, эмоции и поведение: как они связаны',intro='Одна и та же ситуация может восприниматься по-разному. В КПТ мы исследуем, какое значение вы ей придаёте, что при этом чувствуете и как действуете дальше.',desc='На простом примере разбираем связь мыслей, эмоций и поведения в когнитивно-поведенческой терапии. Статья клинического психолога Анастасии Гоевой.',sections=[('Почему важно значение, которое мы придаём ситуации','<p>Когнитивно-поведенческая терапия рассматривает связь между тем, как человек понимает происходящее, его эмоциональной реакцией и действиями. На встрече можно исследовать конкретный эпизод и заметить, в какой момент привычный вывод начинает влиять на дальнейший разговор или решение.</p><p>В работе для меня важно оставаться рядом с вашей реальной ситуацией. Мы уточняем факты, ваши мысли и чувства, а затем обсуждаем, какое действие было бы полезно попробовать.</p>'),('Условный пример: сообщение без ответа','<p>Представим, что вы написали близкому человеку и пока не получили ответа. Факт здесь один: сообщение остаётся без ответа. Дальше может появиться мысль: «Я ему больше не важна». Вместе с ней — тревога или обида, а затем желание снова проверить телефон, отправить ещё несколько сообщений или резко прекратить разговор.</p><p>В этом примере мы можем разбирать каждый шаг: что известно наверняка, что вы предполагаете, какое чувство возникает и что меняется после выбранного действия. Это вымышленная ситуация для объяснения модели, а не история клиента.</p>'),('Что мы можем исследовать на встрече','<p>Я могу предложить вернуться к моменту, который вас задел, и вместе рассмотреть, что вы тогда заметили, подумали, почувствовали и сделали. Иногда полезно записать эти части эпизода, чтобы обсудить их подробнее.</p><p>Дальше мы проверяем, насколько привычный вывод соответствует известным фактам, рассматриваем другие возможные объяснения и выбираем небольшой шаг, который можно попробовать в жизни. Например, прямо уточнить, когда человеку удобно поговорить, если это подходит вашей ситуации.</p>'),('Где в этом месте эмоции и потребности','<p>Тревога или обида остаются важной частью вашего опыта. На встрече можно исследовать, что именно оказалось болезненным и чего вам хотелось от другого человека. Понимание этих деталей помогает сформулировать, с чем вы хотите работать дальше.</p><p>Если вы узнаёте себя в похожих ситуациях, можно принести на консультацию один недавний эпизод. Мы разберём его в вашем темпе и подумаем, какие изменения сейчас имеют для вас смысл.</p>')],cta='Записаться на индивидуальную встречу'),en=dict(title='Thoughts, Feelings and Behavior in CBT | Anastasia Goeva',h1='How thoughts, feelings and behavior connect',intro='The same situation can mean different things to different people. In CBT, we explore the meaning you give it, how you feel, and what you do next.',desc='A simple example of how thoughts, feelings and behavior connect in cognitive behavioral therapy. An article by clinical psychologist Anastasia Goeva.',sections=[('The meaning we attach to a situation','<p>Cognitive behavioral therapy explores connections between how a person understands a situation, their emotional response, and their actions. In a session, we can look at a specific moment and notice when a familiar interpretation begins to shape a conversation or decision.</p><p>I want our work to stay close to your actual experience. We clarify the facts, your thoughts and feelings, then discuss a response that might be worth trying.</p>'),('An example: waiting for a reply','<p>Imagine you have messaged someone close to you and they have not replied yet. All you know at this point is that they haven’t replied. A thought might follow: “I don’t matter to them anymore.” You may feel anxious or hurt, then find yourself checking your phone, sending several more messages, or abruptly withdrawing.</p><p>We can explore each part: what you know, what you are assuming, how you feel, and what happens after you act. This is a fictional example to illustrate the model, not a client story.</p>'),('What we might explore in a session','<p>I may invite you to return to a moment that upset you and look together at what you noticed, thought, felt, and did. Sometimes it is useful to write these parts down so we can consider them more closely.</p><p>We then examine how well the familiar interpretation fits the facts, consider other possible explanations, and choose a small step to try in everyday life. Depending on the situation, that might mean asking directly when the other person is available to talk.</p>'),('Making room for feelings and needs','<p>Anxiety or hurt is an important part of your experience. We can explore what felt painful and what you hoped for from the other person. Understanding those details helps us clarify what you want to work on.</p><p>If this feels familiar, you can bring a recent example to a session. We will explore it at your pace and think about what kind of change matters to you now.</p>')],cta='Book an individual session')),
]

def text(lang,ru,en):return ru if lang=='ru' else en
def filename(slug,lang):return slug+('' if lang=='ru' else '-en')+'.html'
def booking(lang,pair=False):
 msg=text(lang,'Здравствуйте, мы хотим записаться на парную сессию' if pair else 'Здравствуйте, я хочу записаться на сессию','Hello, we’d like to book a couples session' if pair else 'Hello, I’d like to book a session')
 return 'https://t.me/ogogoevaa?'+urlencode({'text':msg}, quote_via=quote)

def price(lang,pair):
 src=(R/('index.html' if lang=='ru' else 'en.html')).read_text()
 tag=text(lang,'Парная встреча' if pair else 'Индивидуальная встреча','Couples session' if pair else 'Individual session')
 match=re.search(r'<article><h3>'+re.escape(tag)+r'</h3>.*?<p class="price">(.*?)</p>',src,re.S)
 if not match:
  # The existing English site uses the same fee cards with slightly different labels.
  cards=re.findall(r'<article><h3>.*?</h3>.*?<p class="price">(.*?)</p>',src,re.S)
  return cards[1 if pair else 0]
 return match[1]

def normalize_main(lang):
 p=R/('index.html' if lang=='ru' else 'en.html');s=p.read_text()
 s=re.sub(r'<p class="service-read-more">.*?</p>', '',s,flags=re.S)
 s=re.sub(r'<section\b[^>]*id="reading".*?</section>\s*','',s,flags=re.S)
 s=re.sub(r'(<section class="wrap section" id="session">\s*<h2>.*?</h2>)\s*<p class="aside">.*?</p>',r'\1',s,count=1,flags=re.S)
 s=re.sub(r'<p class="aside resources-intro">.*?</p>\s*','',s,count=1,flags=re.S)
 s=s.replace('В работе с парами я использую эмоционально-фокусированную терапию (ЭФТ).','В работе с парами я использую ЭФТ (эмоционально-фокусированную терапию).')
 s=s.replace('With couples, I use emotionally focused therapy (EFT).','With couples, I use EFT (emotionally focused therapy).')
 s=s.replace('Anastasia Goeva · Self-employed in Russia (professional income tax)','Anastasia Goeva · Self-employed (NPD)')
 s=re.sub(r'<nav class="footer-resources".*?</nav>\s*','',s,flags=re.S)
 labels=['Индивидуальная терапия','Парная терапия','Подготовка к первой встрече','Мысли, эмоции и поведение в КПТ'] if lang=='ru' else ['Individual therapy','Couples therapy','Your first session','Thoughts, feelings and behavior in CBT']
 s=re.sub(r'<a class="privacy-link"[^>]*>.*?</a>','',s,flags=re.S)
 privacy='<li><a class="privacy-link" href="'+text(lang,'privacy.html','privacy-en.html')+'">'+text(lang,'Политика конфиденциальности','Privacy policy')+'</a></li>'
 nav='<nav class="footer-resources" aria-label="'+text(lang,'Страницы сайта','More pages')+'"><ul>'+privacy+''.join(f'<li><a href="{filename(data["slug"],lang)}">{label}</a></li>' for data,label in zip(DATA,labels))+'</ul></nav>'
 s=re.sub(r'(<footer class="wrap foot site-footer">.*?)(</footer>)',lambda m:m[1]+nav+'\n'+m[2],s,count=1,flags=re.S)
 s=re.sub(r'content\.css\?v=[^"\s]+','content.css?v=footer-inline-4',s)
 p.write_text(s)

for lang in ['ru','en']:normalize_main(lang)

