  body=f'''<main id="main" class="editorial-main"><div class="wrap editorial-breadcrumb"><a href="{home}">{text(lang,'Главная','Home')}</a><span aria-hidden="true">/</span><span>{text(lang,'Консультации' if data['kind']=='service' else 'Статьи','Therapy' if data['kind']=='service' else 'Articles')}</span></div><section class="wrap editorial-hero"><div><p class="editorial-tag">{tag}</p><h1>{d['h1']}</h1><p class="editorial-intro">{d['intro']}</p>{meta}{introactions}<p class="editorial-byline">{text(lang,'Автор: ','By ')}<a href="{home}#about">{text(lang,'Анастасия Гоева','Anastasia Goeva')}</a></p></div><figure class="editorial-visual"><img src="media/{data['image']}" width="512" height="512" alt="" fetchpriority="high"><svg viewBox="0 0 500 100" fill="none" aria-hidden="true"><path pathLength="100" d="M0 55 C80 20 151 90 211 55 C260 27 207 5 191 38 C166 86 345 96 500 42"/></svg></figure></section><div class="wrap article-layout">{toc}<article class="editorial-prose">{sections}{resources}{authorbox}<section class="editorial-booking" id="booking"><h2>{text(lang,'Можно начать с одной встречи','You can start with one session')}</h2><p>{text(lang,'Напишите мне, чтобы согласовать время, формат и способ оплаты. Основные договорённости можно прочитать ','Send me a message to agree on a time, format, and payment method. You can read the practical details ')}<a href="{home}#rules">{text(lang,'перед записью','before you book')}</a>.</p><a class="button" href="{booking(lang,pair)}">{cta}</a></section></article></div></main>'''
